-- +goose Up
-- Master data: Vietnam administrative units post-2025 (34 provinces, 3321 wards)
-- Source: open-admin-data/vietnam-administrative-divisions (updated 2026)

CREATE TABLE IF NOT EXISTS countries (
    code TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    name_en TEXT NOT NULL DEFAULT '',
    is_default BOOLEAN NOT NULL DEFAULT false,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS provinces (
    code TEXT PRIMARY KEY,
    country_code TEXT NOT NULL REFERENCES countries (code) ON DELETE CASCADE,
    name TEXT NOT NULL,
    name_en TEXT NOT NULL DEFAULT '',
    latitude DOUBLE PRECISION,
    longitude DOUBLE PRECISION,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_provinces_country_code ON provinces (country_code);

CREATE TABLE IF NOT EXISTS wards (
    code TEXT PRIMARY KEY,
    province_code TEXT NOT NULL REFERENCES provinces (code) ON DELETE CASCADE,
    name TEXT NOT NULL,
    name_en TEXT NOT NULL DEFAULT '',
    latitude DOUBLE PRECISION,
    longitude DOUBLE PRECISION,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);
CREATE INDEX IF NOT EXISTS idx_wards_province_code ON wards (province_code);

INSERT INTO countries (code, name, name_en, is_default) VALUES ('VN', 'Việt Nam', 'Vietnam', true)
ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, name_en = EXCLUDED.name_en, is_default = EXCLUDED.is_default;

